# frozen_string_literal: true
require 'json'
require 'cgi'
require_relative 'guide_ui'
module TaxGuide
  DATA=JSON.parse(File.read(File.expand_path('../_data/tax-guide.json',__dir__)))
  module_function
  def h(s);CGI.escapeHTML(s.to_s);end
  def source(id,label=nil)
    row=DATA.fetch('sources').find{|r|r['id']==id} || raise(id)
    %(<a href="#{h(row['url'])}" rel="noopener">#{h(label || row['title'])}</a>)
  end
  def page
    holidays=JSON.parse(File.read(File.expand_path('../assets/calendar-data.json',__dir__))).fetch('holidays').select{|r|r['dayOff']}.map{|r|r['date']}.uniq
    %(<article class="benefit-guide tax-guide"><header class="tax-hero"><div><span class="benefit-kicker">LATVIJA · 2026. GADA NODOKĻI</span><h1>No bruto algas līdz summai uz rokas.</h1><p>Aprēķini algu, pārbaudi PVN un atrodi savam statusam atbilstošo nodokļu termiņu. Praktisks ceļvedis ar saitēm uz VID EDS, veidlapām un oficiālajiem skaidrojumiem.</p><div class="benefit-actions"><a class="benefit-button" href="#algas-aprekins">Aprēķināt algu #{GuideUI.icon('arrow')}</a><a href="#nodoklu-termini">Kad jāmaksā nodokļi? #{GuideUI.icon('down')}</a></div><div class="tax-hero-check">#{GuideUI.icon('shield')} Noteikumi pārbaudīti 16.11.2026. · Dati paliek tavā ierīcē.</div></div><div class="tax-hero-art" aria-label="Aprēķina piemērs: 1500 eiro bruto alga, 157,50 eiro sociālās iemaksas, 202,09 eiro IIN un 1140,41 eiro neto alga, ja grāmatiņa ir darbavietā un nav apgādājamo."><div class="tax-paper"><span>ALGAS APRĒĶINS · PIEMĒRS</span><div><small>Bruto alga</small><b>1500,00 €</b></div><div><small>Darba ņēmēja VSAOI</small><b>−157,50 €</b></div><div><small>Iedzīvotāju ienākuma nodoklis</small><b>−202,09 €</b></div><footer><span>Uz rokas</span><strong>1140,41 €</strong></footer><p>Grāmatiņa darbavietā · Bez apgādājamiem</p></div><div class="tax-art-mark"><span>2026</span><b>25,5<small>%</small></b><p>Mēneša IIN likme</p></div></div></header><nav class="benefit-subnav" aria-label="Nodokļu ceļveža sadaļas"><a href="#algas-aprekins">Bruto un neto</a><a href="#pvn">PVN</a><a href="#nodoklu-termini">Termiņi</a><a href="#ka-samaksat">Kā samaksāt</a><a href="#veidlapas">Veidlapas</a></nav>
    <section id="algas-aprekins" class="tax-calculator tax-section"><header class="tax-section-header"><div><span class="benefit-kicker">TAVA ALGA SADALĪJUMĀ</span><h2>Algas un nodokļu kalkulators 2026</h2></div><p>Vienas pilnas mēneša algas modelis Latvijas rezidentam, kas ir apdrošināts Latvijā. Summai virs 8775 eiro un īpašiem režīmiem vajadzīgs individuāls aprēķins.</p></header><div class="tax-salary-grid"><form data-tax-salary><fieldset class="tax-mode"><legend>Ko vēlies aprēķināt?</legend><label><input type="radio" name="mode" value="gross" checked><span>No bruto uz neto</span></label><label><input type="radio" name="mode" value="net"><span>No neto uz bruto</span></label></fieldset><label class="tax-amount">Mēneša algas summa, €<input type="number" name="amount" min="0" max="8775" step="0.01" value="1500" inputmode="decimal" required></label><div class="tax-fields"><label>Darba ņēmēja statuss<select name="status"><option value="standard">Vispārējā kārtība</option><option value="oldage">Vecuma pensijas saņēmējs</option><option value="disability">Invaliditātes pensija, pirms vecuma pensijas vecuma</option><option value="service">Izdienas vai valsts speciālā pensija</option></select></label><label>Algas nodokļa grāmatiņa<select name="book"><option value="yes">Iesniegta šajā darbavietā</option><option value="no">Nav iesniegta šajā darbavietā</option></select></label><label>Apgādājamo skaits<input type="number" name="dependents" min="0" max="10" value="0" step="1"></label><label>Papildu mēneša atvieglojums<select name="extra"><option value="0">Nav</option><option value="154">154 € I/II grupa vai cits atbilstošs statuss</option><option value="120">120 € III invaliditātes grupa</option></select></label></div><label class="tax-check"><input type="checkbox" name="risk" checked><span>Darba devēja izmaksās iekļaut 0,36 € riska nodevu</span></label><button class="benefit-button" type="submit">Atjaunot aprēķinu #{GuideUI.icon('arrow')}</button><p class="tax-small">Atvieglojumiem jābūt piemērojamiem visu aprēķina mēnesi. Pensijas saņēmējam ar grāmatiņu darbavietā algai izmanto 500 € no dalītā minimuma. Rīks neaprēķina pašu pensiju. Neto–bruto virzienā rāda mazāko bruto summu, kas noapaļojot dod izvēlēto neto; iespējama viena centa starpība.</p></form><div class="tax-result-wrap"><div data-tax-result class="tax-result" aria-live="polite"><p>Ieslēdz JavaScript, lai veiktu aprēķinu. Zemāk ir arī pārbaudāms piemērs un formula.</p></div><button class="tax-print-button" data-tax-print disabled>#{GuideUI.icon('document')} Drukāt tikai algas aprēķinu</button></div></div></section>
    <section class="tax-section"><div class="tax-explainer-grid"><div><span class="benefit-kicker">KO NOZĪMĒ REZULTĀTS?</span><h2>Trīs summas, kuras nejaukt</h2><p><b>Bruto alga</b> ir darba līgumā noteiktā summa pirms darbinieka nodokļiem. <b>Neto alga</b> ir aprēķinātais atlikums pēc darbinieka VSAOI un IIN. <b>Darba devēja izmaksas</b> ietver arī darba devēja sociālās iemaksas un attiecīgajā gadījumā riska nodevu.</p><p>Minimums un atvieglojumi samazina IIN apliekamo summu; tie nav atsevišķs pabalsts. Ja pie viena darba devēja grāmatiņas nav, rīks algai nepiemēro ne minimumu, ne apgādājamo atvieglojumu.</p><p>#{source('salary','VID formula un piemēri')} ļauj salīdzināt aprēķinu ar algas lapiņu. Ja nestrādā pilnu mēnesi, ir slimības nauda, vairāki darba devēji vai ārvalstu sociālā apdrošināšana, šis vienkāršotais modelis neder visam norēķinam.</p></div><aside class="tax-formula"><span>2026 · VISPĀRĒJĀ KĀRTĪBA</span><div><b>10,5%</b><p>Darbinieka VSAOI no bruto</p></div><div><b>550 €</b><p>Minimums ar grāmatiņu darbavietā</p></div><div><b>250 €</b><p>Atvieglojums par vienu apgādājamo</p></div><footer>Bruto − VSAOI − IIN = neto</footer></aside></div><div class="tax-notice"><h3>Mēneša ieturējums nav gada gala nodoklis</h3><p>Gada progresijā ienākuma daļai virs 105300 eiro piemēro 33%; virs 200000 eiro var rasties arī 3% papildu likme. Tiek vērtēti dažādi ienākumi, ne tikai viena alga. Šo gala aprēķinu un solidaritātes nodokli šeit nemodelējam. Darba devēja minimālo VSAOI piemaksu, slimības lapas un nepilna mēneša aprēķinu rīks neietver. #{source('rates','Pārbaudi gada likmes VID.')}</p></div></section>
    <section id="pvn" class="tax-section tax-vat"><header class="tax-section-header"><div><span class="benefit-kicker">PIRKUMS VAI RĒĶINS</span><h2>PVN kalkulators</h2></div><p>Pievieno PVN summai bez nodokļa vai izdali PVN no galīgās cenas. Likmi izvēlies pēc konkrētās preces vai pakalpojuma noteikumiem.</p></header><div class="tax-vat-grid"><form data-tax-vat><label>Summa, €<input type="number" name="amount" min="0" max="1000000000" step="0.01" value="100" inputmode="decimal"></label><label>Darbība<select name="mode"><option value="add">Pievienot PVN</option><option value="remove">Izdalīt PVN no cenas</option></select></label><label>PVN likme<select name="rate"><option value="0.21">21% standartlikme</option><option value="0.12">12% samazinātā likme</option><option value="0.05">5% samazinātā likme</option><option value="0">0% atbilstošs darījums</option></select></label></form><div data-tax-vat-result class="tax-vat-result" aria-live="polite"><p>Piemērs: 100 € + 21 € PVN = 121 €.</p></div></div><p class="tax-small">Cena 121 € ar 21% PVN nozīmē 100 € bez PVN un 21 € nodokli nevis 121 × 21%. #{source('vat','VID skaidro, kam piemēro katru likmi.')} 0% likme nav tas pats, kas atbrīvojums no PVN.</p></section>
    <section id="nodoklu-termini" class="tax-section tax-deadlines"><header class="tax-section-header"><div><span class="benefit-kicker">KAD JĀIESNIEDZ UN KAD JĀMAKSĀ?</span><h2>Nodokļu termiņu plāns</h2></div><p>Izvēlies savu pienākumu. Deklarācija un maksājums bieži ir dažādās dienās. Maksājumiem, PVN un gada deklarācijai ievēro pārcelšanu uz nākamo darbdienu. Pašnodarbinātā un MUN deklarāciju brīvdienā ieplāno iesniegt iepriekšējā darbdienā.</p></header><form data-tax-dates class="tax-date-controls"><label>Gads, kurā izpildi pienākumu<select name="year"><option value="2026">2026</option><option value="2027" selected>2027 pēc pašreizējās kārtības</option></select></label><label>Pienākuma veids<select name="kind"><option value="annual">Obligātā gada deklarācija līdz 105300 € ienākumiem</option><option value="annualhigh">Obligātā gada deklarācija virs 105300 € ienākumiem</option><option value="self">Pašnodarbinātā VSAOI ceturksnis</option><option value="mun">Mikrouzņēmumu nodoklis ceturksnis</option><option value="pvnmonth">PVN mēneša periods</option><option value="pvnquarter">PVN ceturkšņa periods</option><option value="employee">Tikai darba alga vai jāmaksā pašam?</option></select></label></form><div data-tax-dates-result></div><div class="tax-date-actions"><button class="benefit-button" type="button" data-tax-dates-export hidden>Pievienot termiņus kalendāram #{GuideUI.icon('download')}</button><a href="https://www.vid.gov.lv/lv/deklaraciju-iesniegsanas-un-nodoklu-nomaksas-termini" rel="noopener">Pārbaudīt VID termiņu noteikumus #{GuideUI.icon('external')}</a></div><p class="tax-small">Ņemtas vērā arī 2026. gada pārceltās darba dienas. Gada deklarācija attiecas uz iepriekšējā gada ienākumiem. Ja deklarācijas termiņš brīvdienā nav likumā pārcelts, ICS failā paredzēta iesniegšana iepriekšējā darbdienā. Kalendārs rāda pamatmaksājumu, nevis brīvprātīgo deklarāciju, individuālu pagarinājumu vai visus dalītos maksājumus. Ja deklarācijā aprēķinātais IIN pārsniedz 640 €, to var maksāt trīs daļās attiecīgajos 23. datumos; precīzu grafiku pārbaudi EDS. ICS failā ir atgādinājums divas dienas iepriekš. Fails pats neatjaunojas.</p><script type="application/json" id="tax-holidays">#{JSON.generate(holidays)}</script></section>
    <section class="tax-section" id="ka-samaksat"><div class="tax-payment-hero"><div><span class="benefit-kicker">OFICIĀLĀ MAKSĀJUMU VIETA</span><h2>Kā samaksāt nodokli?</h2><p>Sāc ar savu VID EDS kontu. Tur redzēsi aprēķināto summu, parādu, pārmaksu un tuvākos maksājumus. Šīs lapas kalkulatora rezultāts nav maksājuma uzdevums.</p><a class="benefit-button" href="https://eds.vid.gov.lv/" rel="noopener">Atvērt VID EDS maksāšanai #{GuideUI.icon('external')}</a><span class="tax-external-note">Tiks atvērta eds.vid.gov.lv · Jāpieslēdzas pašam</span></div><div class="tax-eds-map" aria-label="EDS navigācijas ceļš"><span>VID EDS</span><ol><li><b>01</b> Pieslēdzies savam profilam</li><li><b>02</b> Atver sadaļu “Maksājumi”</li><li><b>03</b> Pārbaudi summu un termiņu</li><li><b>04</b> Veic maksājumu un saglabā apliecinājumu</li></ol></div></div><div class="tax-two-columns"><article><h3>Ja maksā internetbankā</h3><p>Izmanto #{source('account','VID vienotā nodokļu konta rekvizītus')}. Pirms apstiprināšanas pārbaudi saņēmēju, reģistrācijas numuru un nodokļu maksātāja identifikāciju. Ne visiem maksājumiem ir tas pats konts, tāpēc muitas vai pašvaldības maksājumam pārbaudi tieši tā norādījumus.</p><p>Naudas iemaksa kontā un konkrētas saistības segšana nav viens un tas pats. EDS pārbaudi, kā maksājums attiecināts; savlaicīgi iemaksāta nauda līdz termiņam var būt neattiecināta.</p></article><article><h3>Ja ir parāds vai trūkst naudas</h3><p>Neizvēlies patvaļīgu grafiku. EDS noskaidro, par kuru periodu ir saistība, un sazinies ar VID par attiecīgajai situācijai iespējamo termiņa pagarinājumu. Formāls iesniegums un VID lēmums atšķiras no parasta maksājuma sadalīšanas internetbankā.</p><p>Saziņai izmanto EDS sadaļu “Sarakste ar VID”. Kalkulatoram nav vajadzīgs tavs personas kods, bankas konts vai pieslēgšanās dati.</p></article></div></section>
    <section id="veidlapas" class="tax-section"><span class="benefit-kicker">NO APRĒĶINA LĪDZ DOKUMENTAM</span><h2>Kuru veidlapu vai pakalpojumu atvērt?</h2><div class="tax-form-cards"><article><span class="tax-form-symbol">D</span><h3>Gada ienākumu deklarācija</h3><p>Pārbaudi algu un pensiju datus, pievieno attaisnotos izdevumus un atbilstošās ienākumu sadaļas. Deklarācija par 2026. gadu ir 2027. gada process.</p><a href="https://www.vid.gov.lv/lv/gada-ienakumu-deklaracija">Atvērt deklarācijas ceļvedi #{GuideUI.icon('external')}</a></article><article><span class="tax-form-symbol">EDS</span><h3>Algas nodokļa grāmatiņa</h3><p>Norādi galveno darbavietu, apgādājamos un piemērojamos atvieglojumus. Izmaiņas ietekmē darba devēja saņemto informāciju un algas aprēķinu.</p>#{source('book','Atvērt grāmatiņas norādes')}</article><article><span class="tax-form-symbol">VSAOI</span><h3>Pašnodarbinātā ziņojums</h3><p>VSAOI ziņojums un gada IIN deklarācija ir atšķirīgi pienākumi. Vispirms pārliecinies par savu reģistrēto režīmu un ceturkšņa datiem.</p>#{source('business','Atvērt saimnieciskās darbības ceļvedi')}</article><article><span class="tax-form-symbol">PDF</span><h3>VID veidlapu katalogs</h3><p>Lejupielādē aktuālo veidlapu vai pārbaudi tās nosaukumu. Saimnieciskās darbības deklarēšanā var būt obligāta elektroniska iesniegšana EDS.</p>#{source('forms','Atvērt oficiālās veidlapas')}</article></div><div class="tax-notice"><h3>Ko nozīmē D1, D2, D3 un D4?</h3><p>D1 attiecas uz Latvijas ienākumiem, D2 uz attiecīgi deklarējamiem ārvalstu ienākumiem, D3 uz saimniecisko darbību vienkāršā ieraksta sistēmā, bet D4 uz attaisnotajiem izdevumiem. Tā ir orientācija, nevis visu pielikumu saraksts. EDS izvēle ir atkarīga no reālajiem ienākumiem un dokumentiem. #{source('annual','VID deklarācijas skaidrojums')} palīdz izvēlēties nepieciešamās sadaļas.</p></div></section>
    <section class="tax-section tax-faq"><h2>Bieži jautājumi par algu un nodokļiem</h2><details><summary>Cik saņemšu uz rokas no 1500 eiro bruto?</summary><p>2026. gada piemērā ar 10,5% darbinieka VSAOI, grāmatiņu darbavietā un bez apgādājamiem: VSAOI ir 157,50 €, IIN ir 202,09 €, neto alga ir 1140,41 €. Darba devēja iemaksas šajā summā neietilpst.</p></details><details><summary>Vai grāmatiņas neiesniegšana nozīmē, ka nauda ir zaudēta?</summary><p>Darba devējs šajā algā nepiemēro minimumu un atvieglojumus. Gada deklarācijā iespējams pārrēķins, taču rezultāts ir atkarīgs arī no pārējiem ienākumiem un jau piemērotajiem atvieglojumiem. Kalkulators negarantē atmaksu.</p></details><details><summary>Vai 500 eiro minimumu pensionāram pieskaita pie 550 eiro?</summary><p>Nē. Strādājošam pensijas saņēmējam ar grāmatiņu darbavietā algai paredzēts 500 € no dalītā pensionāra minimuma. Tas nav parastā 550 € minimuma papildinājums.</p></details><details><summary>Vai katram nodoklim maksāšanas termiņš ir 23. datums?</summary><p>Nē. 23. datums ir izplatīts regulāro maksājumu termiņš vienotajā kontā, bet ir gada deklarācijas nosacījumi, citas saistības un VID individuālie lēmumi. Deklarācijas iesniegšanas diena arī var atšķirties.</p></details><details><summary>Vai šeit var iesniegt deklarāciju vai samaksāt nodokli?</summary><p>Nē. Aprēķini notiek pārlūkā. Pogas ved uz oficiālo VID pakalpojumu; personas datus un deklarāciju iesniedz tur, un maksājumu apstiprini pats.</p></details><details><summary>Vai PVN kalkulators izvēlas likmi manā vietā?</summary><p>Nē. Tas aprēķina izvēlētās likmes matemātiku. Darījuma veids, datums, atbrīvojumi un reģistrācijas statuss jāizvērtē pēc VID noteikumiem.</p></details></section><nav class="tax-related" aria-label="Saistītie rīki"><a href="/pensiju-izmaksas/">Pensijas vecums un izmaksas #{GuideUI.icon('arrow')}</a><a href="/darba-dienu-kalendars/">Darba dienu aprēķins #{GuideUI.icon('arrow')}</a><a href="/pabalstu-izmaksas/">Pabalsti un sociālais atbalsts #{GuideUI.icon('arrow')}</a></nav></article>)
  end
  def notes
    {'heading'=>'Nodokļa aprēķins un maksājums ir atsevišķi soļi','paragraphs'=>['2026. gada algas modelis atdala darbinieka sociālās iemaksas, IIN un darba devēja izmaksas. No bruto summas atskaita darbinieka VSAOI un IIN; atvieglojumi samazina tikai IIN bāzi. Gada progresija un citi ienākumi var radīt vēlāk veicamu pārrēķinu.','PVN rīks izdala nodokļa daļu no cenas vai pievieno nodokli izvēlētajai bāzei. Termiņu plāns palīdz sagatavoties deklarācijai, bet precīzo saistību, summu un oficiālo maksāšanas vietu pārbaudi VID EDS.'],'icon'=>'calculator','sources'=>DATA['sources'].first(3),'related'=>[{'url'=>'/pensiju-izmaksas/','title'=>'Pensijas plānošana'},{'url'=>'/darba-dienu-kalendars/','title'=>'Darba dienu aprēķins'}]}
  end
end
